import{s}from"/dist/chunk-6k8ey1xy.js";function e(){return s("div",{class:"markdown-body",dangerouslySetInnerHTML:{__html:`<h1>rsync 简明使用教程</h1><p>rsync 是一个文件同步软件，支持本地计算机和远程计算机之间进行文件同步。rsync 可以理解为 cp、mv 命令的威力加强版。</p><h2>基本使用</h2><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#B392F0">rsync</span><span style="color:#79B8FF"> -r</span><span style="color:#9ECBFF"> src</span><span style="color:#9ECBFF"> dest</span></span>
<span class="line"></span></code></pre><p>表示将 src 目录复制到 dest 目录。注意是 src 目录本身及其子目录。</p><p><strong>如果只想同步 src 目录下的文件，需要改为 src/</strong>：<code>rsync -r src/ dest</code></p><h2><code>-a</code> 同步元数据</h2><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#B392F0">rsync</span><span style="color:#79B8FF"> -a</span><span style="color:#9ECBFF"> src/</span><span style="color:#9ECBFF"> dest</span></span>
<span class="line"></span></code></pre><p>-a 和 -r 基本一致。但会复制文件的元数据</p><h2><code>-n</code> 试运行</h2><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#B392F0">rsync</span><span style="color:#79B8FF"> -anv</span><span style="color:#9ECBFF"> src/</span><span style="color:#9ECBFF"> dest</span></span>
<span class="line"></span></code></pre><p>增加 -n 表示 --dry-run。不会实际操作文件，用于测试一下执行的效果。</p><h2><code>--delete</code> 同步删除文件</h2><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#B392F0">$</span><span style="color:#9ECBFF"> rsync</span><span style="color:#79B8FF"> -av</span><span style="color:#79B8FF"> --delete</span><span style="color:#9ECBFF"> src/</span><span style="color:#9ECBFF"> dest</span></span>
<span class="line"></span></code></pre><p>增加 --delete 会删除 dest 目录下存在但 src 目录没有的文件。执行后 dest 就成了 src 的镜像。</p><h2>示例</h2><p>我使用 rsync 主要冷备份。我自组的 NAS 有四个硬盘：</p><table><thead><tr><th>挂载点</th><th>容量</th></tr></thead><tbody><tr><td>/dev/sda1</td><td>4TB</td></tr><tr><td>/dev/sdc1</td><td>1TB</td></tr><tr><td>/dev/sdd1</td><td>1TB</td></tr><tr><td>/dev/sde1</td><td>500GB</td></tr></tbody></table><p>一般情况下，我先将数据从其他设备（主要是手机）通过 syncthing 上传到 NAS 的一个硬盘，比如上面的 /dev/sdc1，再通过 rsync 同步到其他硬盘。</p><p>具体操作如下：</p><ol><li>使用手机端的 syncthing 同步文件到 /mnt/sdc1/sync 目录下</li><li>执行 <code>rsync -av --delete /mnt/sdc1/ /mnt/sdd1</code></li><li>执行 <code>rsync -av /mnt/sdc1/ /mnt/sda1</code></li></ol><hr /><ul><li>2024 年 8 月 4 日 初稿</li></ul>`}},void 0,!1,void 0,this)}export{e as default};
